44:       }
45: 
46:       const totalTime = performance.now() - start;
47:       debugLog(
48:         `Flushed ${mergedDeviceUpdates.length + mergedPositionUpdates.length} / ${flushed.length} events in ${totalTime.toFixed(2)} ms`,
49:       );
50:       currentInterval = Math.min(Math.max(totalTime * scaleFactor, minInterval), maxInterval);
51:     }
52: 
53:     const shouldThrottle = (counter * 1000) / currentInterval > threshold;
54:     if (throttled != shouldThrottle) {
55:       debugLog(`Throttling ${shouldThrottle}`);
56:       throttled = shouldThrottle;
57:     }
58:     counter = 0;
59:     if (!throttled) currentInterval = minInterval;
60:     setTimeout(tick, currentInterval);
61:   };
